/*
 * The sample files the empty state offers.
 *
 * A new user has no PDF, no photo and no recording, so every capability tile
 * dead-ends at "attach a file". These are real files, generated by
 * `scripts/make-samples.mjs`, so the first click can actually do something.
 */

export type SampleFile = {
  /** The family this demonstrates, matching `capabilities[].id`. */
  capability: string;
  filename: string;
  /** Path under `public/`, without the base path. */
  href: string;
  /** What the button says. */
  label: string;
  mediaType: string;
  /** What is asked once the file is attached. */
  prompt: string;
};

export const samples: SampleFile[] = [
  {
    capability: "pdf",
    filename: "quarterly-report.pdf",
    href: "/samples/quarterly-report.pdf",
    label: "Report PDF",
    mediaType: "application/pdf",
    prompt: "Summarise this PDF and list its key figures.",
  },
  {
    capability: "images",
    filename: "product-photo.png",
    href: "/samples/product-photo.png",
    label: "Photo",
    mediaType: "image/png",
    prompt: "Remove the background from this photo.",
  },
  {
    capability: "sheets",
    filename: "regional-sales.csv",
    href: "/samples/regional-sales.csv",
    label: "Sales CSV",
    mediaType: "text/csv",
    prompt:
      "Summarise this spreadsheet and tell me which region is growing fastest.",
  },
  {
    capability: "documents",
    filename: "quarterly-report.md",
    href: "/samples/quarterly-report.md",
    label: "Report",
    mediaType: "text/markdown",
    prompt: "Summarise this document and give me its outline.",
  },
  {
    capability: "audio",
    filename: "sample-recording.wav",
    href: "/samples/sample-recording.wav",
    label: "Recording",
    mediaType: "audio/wav",
    prompt: "Show me the waveform of this recording and transcribe it.",
  },
];

/** The sample for a family, when there is one. */
export function sampleFor(capabilityId: string): SampleFile | undefined {
  return samples.find((sample) => sample.capability === capabilityId);
}
